 11	/**
 12	 * The account's game phase, from host reads only (architecture step 4, RV-011): one answer every manager,
 13	 * the doctrine and the raid ladder read instead of restating a milestone of their own.
 14	 *
 15	 * The class names no object and holds no threshold. `resources/behavior/phase.yaml` names what marks each
 16	 * phase — the planets the account has settled beyond the ones the universe registers for it, and the
 17	 * researched technology whose level means it has outgrown its mines — so a modded universe moves the
 18	 * phases without an edit here.
 19	 */
 20	class GamePhaseMachine
 21	{
 22	    /** Module root relative, so the phase's reads are loaded by name. */
 23	    private const POLICY = '/resources/behavior/phase.yaml';
 24	
 25	    /** @var array<string, mixed>|null */
 26	    private static ?array $policy = null;
 27	
 28	    /** How far the account has come: the opening settled nothing of its own, mid has, late outgrew its mines. */
 29	    public function of(PlayerService $player): GamePhase
 30	    {
 31	        if ($this->outgrownTheMines($player)) {
 32	            return GamePhase::Late;
 33	        }
 34	
 35	        $settled = $player->planets->planetCount() - $this->registrationPlanets();
 36	
 37	        return $settled >= $this->int('mid.settled_planets', 1) ? GamePhase::Mid : GamePhase::Early;
 38	    }
 39	
 40	    /**
 41	     * RV-011's target-class rung: which opponents the account may hit, which the source ties to the
 42	     * planets it owns — the opening is a single planet, and a second one lets it answer a neighbour who
 43	     * is at the keyboard. A universe that hands a new account more than one planet at registration
 44	     * reaches that rung with its own first colony, which is why the rung counts owned planets and the
 45	     * account's phase counts only the ones the account settled itself.
 46	     */
 47	    public function targetRung(PlayerService $player): GamePhase
 48	    {
 49	        if ($this->outgrownTheMines($player)) {
 50	            return GamePhase::Late;
 51	        }
 52	
 53	        return $player->planets->planetCount() >= $this->int('mid.owned_planets', 2) ? GamePhase::Mid : GamePhase::Early;
 54	    }
 55	
 56	    /**
 57	     * Whether the account has researched the late marker at its level. A universe whose data names no
 58	     * technology, or names one the host does not have, keeps every account below late rather than
 59	     * failing the read.
 60	     */
 61	    private function outgrownTheMines(PlayerService $player): bool
 62	    {
 63	        $technology = (string) ($this->policy()['late']['technology'] ?? '');
 64	        if ($technology === '') {
 65	            return false;
 66	        }
 67	
 68	        try {
 69	            return $player->getResearchLevel($technology) >= $this->int('late.level', PHP_INT_MAX);
 70	        } catch (Throwable) {
 71	            return false;
 72	        }
 73	    }
 74	
 75	    /** The planets the host hands every new account, which the account did not settle itself. */
 76	    private function registrationPlanets(): int
 77	    {
 78	        return app(SettingsService::class)->registrationPlanetAmount();
 79	    }
 80	
 81	    private function int(string $path, int $fallback): int
 82	    {
 83	        $value = $this->policy();
 84	
 85	        foreach (explode('.', $path) as $segment) {
 86	            $value = is_array($value) ? ($value[$segment] ?? null) : null;
 87	        }
 88	
 89	        return is_numeric($value) ? (int) $value : $fallback;
 90	    }
 91	
 92	    /** @return array<string, mixed> */
 93	    private function policy(): array
 94	    {
 95	        if (self::$policy !== null) {
 96	            return self::$policy;
 97	        }
 98	
 99	        $path = dirname(__DIR__, 3) . self::POLICY;
100	        $parsed = is_file($path) ? Yaml::parseFile($path) : [];
101	
102	        return self::$policy = is_array($parsed) ? $parsed : [];
103	    }
104	}

