 9	/**
10	 * The per-archetype numbers the login managers run on (`resources/doctrine/managers.yaml`). A missing
11	 * archetype or key falls back to the file's `default` section, so a new archetype plays like an average one.
12	 *
13	 * A phase may scale a manager's numbers (`phases: <phase>: <key>`): the archetype's own number stays the
14	 * base and the phase's value multiplies it. A phase or key the file does not name multiplies by one, so a
15	 * missing phase changes nothing (Gate 1).
16	 */
17	class ManagerDoctrine
18	{
19	    private const FILE = '/resources/doctrine/managers.yaml';
20	
21	    /** @var array<string, array<string, mixed>>|null */
22	    private static ?array $table = null;
23	
24	    public function int(AiArchetype $archetype, string $key, ?GamePhase $phase = null): int
25	    {
26	        return (int) round($this->value($archetype, $key, 0) * $this->scale($archetype, $phase, $key));
27	    }
28	
29	    public function bool(AiArchetype $archetype, string $key): bool
30	    {
31	        return (bool) $this->value($archetype, $key, false);
32	    }
33	
34	    /** The multiplier this phase gives the key, from the archetype's own phase block or the default one. */
35	    private function scale(AiArchetype $archetype, ?GamePhase $phase, string $key): float
36	    {
37	        if ($phase === null) {
38	            return 1.0;
39	        }
40	
41	        $table = self::table();
42	
43	        foreach ([$table[strtolower($archetype->name)] ?? [], $table['default'] ?? []] as $row) {
44	            $phases = $row['phases'] ?? null;
45	            $phaseRow = is_array($phases) ? ($phases[$phase->value] ?? null) : null;
46	            $value = is_array($phaseRow) ? ($phaseRow[$key] ?? null) : null;
47	
48	            if (is_numeric($value)) {
49	                return (float) $value;
50	            }
51	        }
52	
53	        return 1.0;
54	    }
55	
56	    private function value(AiArchetype $archetype, string $key, mixed $fallback): mixed
57	    {
58	        $table = self::table();
59	        $row = $table[strtolower($archetype->name)] ?? [];
60	
61	        return $row[$key] ?? $table['default'][$key] ?? $fallback;
62	    }
63	
64	    /** @return array<string, array<string, mixed>> */
65	    private static function table(): array
66	    {
67	        if (self::$table !== null) {
68	            return self::$table;
69	        }
70	
71	        $path = dirname(__DIR__, 3) . self::FILE;
72	        $parsed = is_file($path) ? Yaml::parseFile($path) : [];
73	
74	        return self::$table = is_array($parsed) ? $parsed : [];
75	    }
76	}

